/*
 * Does this process execute 32-bit shellcode?
 *
 * This separates two explanations for a Windows/386 shellcode payload that never
 * calls back:
 *
 *   A. the generated bytes are wrong (a c2tool / Sliver defect), or
 *   B. the bytes are fine, but the process decoding them is in 64-bit mode and
 *      32-bit-only instructions are not valid there.
 *
 * The design is one blob per process, chosen by argv, because the interesting
 * outcome is a crash. A crash cannot be caught and reported by the process that
 * caused it -- an earlier draft tried, with a vectored exception handler, and
 * the handler itself terminated the process, so the run produced no output at
 * all. Running one blob per child and reading the exit code turns "it died" into
 * a value.
 *
 * x64:  xor eax,eax ; ret    -> 48 31 C0 C3   valid in both modes
 * x86:  pushad ; ret         -> 60 C3         INVALID in 64-bit mode
 *
 * 0x60 is PUSHAD in 32-bit mode and an illegal opcode in 64-bit mode, where that
 * encoding space became REX prefixes. So the x64 blob is the control: if it
 * returns and the x86 blob dies, the process cannot run 32-bit code.
 *
 * ASCII only.
 *
 * Build:  gcc -O0 -o archprobe.exe archprobe.c
 * Usage:  archprobe.exe x64 | archprobe.exe x86
 */

#include <windows.h>
#include <stdio.h>
#include <string.h>

static unsigned char x64_bytes[] = { 0x48, 0x31, 0xC0, 0xC3 };
static unsigned char x86_bytes[] = { 0x60, 0xC3 };

int main(int argc, char **argv) {
    const char *which = (argc >= 2) ? argv[1] : "x64";
    unsigned char *code;
    size_t len;

    if (strcmp(which, "x64") == 0) {
        code = x64_bytes;
        len = sizeof(x64_bytes);
    } else if (strcmp(which, "x86") == 0) {
        code = x86_bytes;
        len = sizeof(x86_bytes);
    } else {
        printf("usage: %s x64|x86\n", argv[0]);
        return 2;
    }

    SYSTEM_INFO si;
    GetNativeSystemInfo(&si);

    LPVOID mem = VirtualAlloc(NULL, len, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!mem) {
        printf("[%s] VirtualAlloc failed: %lu\n", which, GetLastError());
        return 3;
    }
    memcpy(mem, code, len);
    FlushInstructionCache(GetCurrentProcess(), mem, len);

    printf("[%s] pid %lu, native machine %u, calling %zu byte(s) at %p\n",
           which, (unsigned long)GetCurrentProcessId(), si.wProcessorArchitecture, len, mem);
    fflush(stdout);

    typedef void (*entry_t)(void);
    ((entry_t)mem)();

    printf("[%s] returned cleanly -- this encoding is valid here\n", which);
    VirtualFree(mem, 0, MEM_RELEASE);
    return 0;
}